def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The nonzero cells in the top row define vertical rays.
    anchors = {c: grid[0][c] for c in range(w) if grid[0][c] != 0}

    # A matching marker elsewhere in the grid bends that color's ray
    # horizontally on the marker's row; otherwise the ray runs to the edge.
    for c, color in anchors.items():
        markers = [(r, x) for r in range(1, h) for x in range(w)
                   if grid[r][x] == color]
        stop_row = markers[0][0] if markers else h - 1

        for r in range(stop_row + 1):
            out[r][c] = color

        for r, x in markers:
            if r == stop_row:
                for y in range(min(c, x), max(c, x) + 1):
                    out[r][y] = color

    return out
